import{z as s,x as o,o as e,c as n,q as i,j as A,D as E,d as t,s as B,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"参数量：深度与宽度","description":"","frontmatter":{"title":"参数量：深度与宽度","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/params-depth-width.md","filePath":"llm/params-depth-width.md","lastUpdated":1791063341000}'),p={name:"llm/params-depth-width.md"};function m(h,a,D,F,P,f){const l=o("Mermaid");return e(),n("div",null,[a[2]||(a[2]=i('<h1 id="参数量-深度与宽度" tabindex="-1">参数量：深度与宽度 <a class="header-anchor" href="#参数量-深度与宽度" aria-label="Permalink to &quot;参数量：深度与宽度&quot;">​</a></h1><div class="epigraph"><p>同一参数预算可以铺成很宽的浅网，或很窄的深网；表达力与可训练性对这两种花法并不对称。</p><footer>—— 据 Goodfellow, Bengio &amp; Courville, Deep Learning, 2016；He et al., Deep Residual Learning for Image Recognition, CVPR 2016 整理</footer></div><p><a href="/llm/why-init">初始化为何需要</a>让深栈在起点上信号不灭。本课不重推 \\(1/d_{\\mathrm{in}}\\)。缺口是：仿射层参数量 \\(d_{\\mathrm{in}}d_{\\mathrm{out}}\\)，总预算 \\(P\\) 可以用来加宽某一层，或用来多叠几层。后课残差正是因为「只加深度」在普通栈上失败才出现。本课先把账与几何分开：参数量不是层数，也不是宽度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层 \\(d\\times d\\) 的方阵有 \\(d^2\\) 个参数（加 \\(d\\) 个偏置）。\\(L\\) 层同宽 MLP 大约 \\(L d^2\\)。把 \\(L\\) 减半、\\(d\\) 乘 \\(\\sqrt{2}\\)，参数量相近，但函数类不同：宽浅网是一次高维分段线性，深窄网是多次复合。缺口不是「参数越多越好」的口号，而是同一 \\(P\\) 下深度与宽度不可互换，且可训练性随深度恶化更快——上一单元的 \\(\\rho^L\\) 只惩罚 \\(L\\)，不直接惩罚 \\(d\\)。</p><p><span class="marginnote">数字实例：\\(d=1024\\) 时一层方阵约 \\(1024^2\\approx 105\\) 万参数，12 层同宽栈约 \\(1.26\\times 10^7\\)。把层数减半到 6、宽度乘 \\(\\sqrt2\\approx 1.41\\)（变成约 1448），单层约 209 万，总账仍是约 \\(1.26\\times 10^7\\)——参数几乎没动，但复合次数从 12 次掉到 6 次，函数类已经换了一个。</span></p><p>宽度增加主要增加每一段仿射的秩与通道数，优化更接近「多一些并列的特征」。深度增加折点的组合次数，理论上用较少参数拟合某些高变函数，但反向路径变长。经验上，没有旁路时，加层很快遇到训练误差反而升高——He 等人观察到的「退化」，不是过拟合（训练误差也变差），而是优化失败。那是下一课残差的动机，本课先把退化与「参数不够」区分开。</p><h3 id="参数量不是-flops-也不是容量的唯一度量" tabindex="-1">参数量不是 FLOPs，也不是容量的唯一度量 <a class="header-anchor" href="#参数量不是-flops-也不是容量的唯一度量" aria-label="Permalink to &quot;参数量不是 FLOPs，也不是容量的唯一度量&quot;">​</a></h3><p>一次前向的计算量还随序列长度、批大小变；嵌入表 \\(|V|\\times d\\) 可以占掉很大一块 \\(P\\)，却几乎不增加深度。两模型 \\(P\\) 相同，一个把预算花在词表，一个花在层，行为完全不同。本课谈 MLP 栈时，默认 \\(P\\) 指隐藏层的 \\(W\\)，不含词表。把「十亿参数」当成唯一容量数字，后课嵌入与注意力的账会对不上。</p><p><span class="marginnote">同宽 MLP 里，中间层 \\(d_{\\mathrm{ff}}\\) 往往比模型宽度 \\(d\\) 大几倍，参数量由 \\(2Ld\\,d_{\\mathrm{ff}}\\) 一类式子主导。宽一层与深一层的交换率是 \\(d_{\\mathrm{ff}}\\) 对 \\(L\\)，不是对 \\(d\\) 单独看。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账：列出每张 \\(W\\) 的 \\(d_{\\mathrm{in}}d_{\\mathrm{out}}\\)，加偏置，加嵌入表。比较结构时固定 \\(P\\) 再变 \\(L\\) 与 \\(d\\)，否则「更深更好」可能只是「更大更好」。观察训练误差（不是验证误差）是否随 \\(L\\) 上升：若上升，是退化 / 优化问题；若训练误差下降而验证上升，是上一单元的过拟合。两条曲线要同时看。</p>',12)),(e(),A(d,null,{default:E(()=>[B(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%9B%BA%E5%AE%9A%E5%8F%82%E6%95%B0%E9%A2%84%E7%AE%97%22%5D%20--%3E%20WIDE%5B%22%E6%9B%B4%E5%AE%BD%E6%9B%B4%E6%B5%85%22%5D%0A%20%20P%20--%3E%20DEEP%5B%22%E6%9B%B4%E7%AA%84%E6%9B%B4%E6%B7%B1%22%5D%0A%20%20WIDE%20--%3E%20PAR%5B%22%E5%B9%B6%E5%88%97%E6%9B%B4%E5%A4%9A%E9%80%9A%E9%81%93%22%5D%0A%20%20DEEP%20--%3E%20COMP%5B%22%E6%9B%B4%E5%A4%9A%E5%A4%8D%E5%90%88%20%E4%BD%86%E5%8F%8D%E5%90%91%E6%9B%B4%E9%95%BF%22%5D%0A%20%20COMP%20--%3E%20DEG%5B%22%E6%97%A0%E6%97%81%E8%B7%AF%E6%97%B6%E8%AE%AD%E7%BB%83%E8%AF%AF%E5%B7%AE%E5%8F%AF%E8%83%BD%E5%8D%87%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"表达力定理说：深度对某些函数可以指数地节省宽度。定理不管可训练性。实践中的有效容量是「优化器能走到的那部分函数类」。过深的普通栈把有效容量用没了，尽管 \\(P\\) 很大。加宽则让每层更好拟合残差目标，但单层仍是一次仿射+\\(\\sigma\\)，复合次数少。残差将允许「深」而不付满 \\(\\rho^L\\) 的代价；本课只准备好：看到训练误差随深度变差，不要先加参数，先问路径结构。",-1)),(e(),A(d,null,{default:E(()=>[B(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%AE%AD%E7%BB%83%E8%AF%AF%E5%B7%AE%E9%9A%8F%E5%8A%A0%E6%B7%B1%E8%80%8C%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20Q1%7B%22%E8%AE%AD%E7%BB%83%E8%AF%AF%E5%B7%AE%E6%9C%AC%E8%BA%AB%E5%9C%A8%E5%8D%87%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20DEG%5B%22%E9%80%80%E5%8C%96%EF%BC%9A%E4%BC%98%E5%8C%96%E5%A4%B1%E8%B4%A5%EF%BC%8C%E4%B8%8D%E6%98%AF%E5%8F%82%E6%95%B0%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20DEG%20--%3E%20FIX%5B%22%E5%85%88%E9%97%AE%E8%B7%AF%E5%BE%84%E7%BB%93%E6%9E%84%EF%BC%88%E6%AE%8B%E5%B7%AE%E6%97%81%E8%B7%AF%EF%BC%89%EF%BC%8C%E5%88%AB%E6%80%A5%E7%9D%80%E5%8A%A0%20P%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E6%98%AF%E9%AA%8C%E8%AF%81%E8%AF%AF%E5%B7%AE%E5%9C%A8%E5%8D%87%22%7C%20OVER%5B%22%E8%BF%87%E6%8B%9F%E5%90%88%EF%BC%9A%E5%87%BD%E6%95%B0%E7%B1%BB%E5%A4%AA%E5%A4%A7%22%5D%0A%20%20OVER%20--%3E%20REG%5B%22%E6%AD%A3%E5%88%99%20%2F%20%E5%87%8F%E5%8F%82%20%2F%20%E5%A2%9E%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">直觉类比：深度像接力赛的棒数，宽度像每棒运动员的手臂数。棒数多，动作层层组合能拼出精细套路，但任何一棒掉棒（信号衰减）全队完蛋；手臂数多，每一棒都稳、好练，却终究只是一次性动作。表达力定理夸的是前者潜力大，可训练性提醒的是后者更容易真的跑完。</span></p><p>宽度也不是免费： \\(d\\) 加倍，一层参数乘四（方阵），激活内存与注意力将来的 \\(n^2 d\\) 都会涨。只报 \\(P\\) 不报 \\(d\\) 与 \\(n\\)，无法判断是算力墙还是容量墙。嵌入表 \\(|V|\\times d\\) 随 \\(d\\) 线性涨，随 \\(|V|\\) 线性涨，与层数无关——三本账要分开才能决定下一课该加旁路还是该加宽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入残差公式，不比较 Transformer 与 MLP 的参数分配。下一课<a href="/llm/why-residual">残差的动机</a>专门对付退化。后课默认：报模型大小时分开深度、宽度、词表；比较结构时尽量固定 \\(P\\) 或固定 FLOPs 之一并声明。</p><p><span class="marginnote">常见误区：「7B 模型一定比 6B 强」。若 6B 把预算花在更深的复合上、7B 花在更大的嵌入表上，二者行为可能完全不同。参数量、FLOPs、词表大小是三本独立的账，只报一个总数没法判断你撞的是算力墙还是容量墙。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同参数预算下，深度与宽度不可互换；\\(\\rho^L\\) 主要惩罚深度。</li><li>更深导致训练误差升高是退化，不是过拟合。</li><li>参数量、FLOPs、词表大小是三本账。</li><li>有效容量受可训练性约束，不是 \\(P\\) 的同义词。</li><li>出处：Goodfellow et al., Deep Learning, 2016；He et al., CVPR 2016。</li></ul>',7))])}const u=s(p,[["render",m]]);export{_ as __pageData,u as default};
